  function restartQuestion(){gameState.gamePaused=false;showScreen('game-screen');loadQuestion(gameState.currentQuestion)}
  function loseLife(){gameState.lives=Math.max(0,gameState.lives-1)}
  function useHint(){if(!gameState.currentQuestion||gameState.hintsRemaining<=0){toast('Hakuna hint iliyobaki kwa sasa.');return}gameState.hintsRemaining--;gameState.hintUsed=true;const q=gameState.currentQuestion;if(q.type==='multiple-choice'){const wrong=balls.find(b=>b.text!==q.answer&&!b.selected);if(wrong){wrong.selected=true;wrong.el.classList.add('selected')}}else{const expected=normalize(q.answer)[gameState.selectedLetters.length];toast(`Joka Kodi anasema: Anza na “${expected}”.`);balls.filter(b=>b.text!==expected&&!b.selected).slice(0,1).forEach(b=>{b.el.style.opacity='.35'})}$('feedback-line').textContent=q.hintSw;gameState.timerRemaining=Math.max(1,gameState.timerRemaining-1);updateTimerUI();saveGameState()}
  function openSource(){const q=gameState.currentQuestion;if(q?.sourceLabel)toast(`${q.sourceLabel} · tra.go.tz`)}
  function unlockAchievements(q){const ids=gameState.achievements;if(q.id.includes('tin')&&!ids.includes('tin'))ids.push('tin');if(q.id.includes('tra')&&!ids.includes('tra'))ids.push('tra');if(q.id.includes('vat')&&!ids.includes('vat'))ids.push('vat');if(gameState.combo>=3&&!ids.includes('streak'))ids.push('streak');if((gameState.levelProgress[gameState.currentLevel].correct||0)>=5&&!ids.includes('letters'))ids.push('letters')}
  function completeLevel(){stopTimer();stopMovement();const p=gameState.levelProgress[gameState.currentLevel],total=Math.max(1,p.total||10),accuracy=Math.round(((p.correct||0)/total)*100),stars=accuracy>=90?3:accuracy>=70?2:1;p.completed=true;p.bestScore=Math.max(p.bestScore,gameState.score);p.stars=Math.max(p.stars,stars);p.accuracy=accuracy;gameState.achievements=gameState.achievements.includes('builder')?gameState.achievements:[...gameState.achievements,'builder'];if(gameState.currentLevel<3&&!gameState.unlockedLevels.includes(gameState.currentLevel+1))gameState.unlockedLevels.push(gameState.currentLevel+1);if(gameState.currentLevel===3&&!gameState.achievements.includes('winner'))gameState.achievements.push('winner');saveGameState();$('complete-title').textContent=`Hongera, ${gameState.player.name||'Mjenzi'}!`;$('complete-level-name').textContent=`Umemaliza ${KZ_LEVELS[gameState.currentLevel].nameSw}`;$('complete-stats').innerHTML=`<span class="stat"><b>${gameState.score}</b>Alama</span><span class="stat"><b>${'★'.repeat(stars)}${'☆'.repeat(3-stars)}</b>Nyota</span><span class="stat"><b>${accuracy}%</b>Usahihi</span><span class="stat"><b>${gameState.bestCombo}</b>Combo bora</span>`;$('badge-unlock').textContent=`🏅 Umefungua: ${stars>=2?'Mjenzi wa Taifa':'Mchezaji Mvumilivu'}`;showScreen('level-complete-screen');confettiBurst()}
  function toggleSound(){gameState.settings.soundEnabled=!gameState.settings.soundEnabled;renderSettings();toast(gameState.settings.soundEnabled?'Sauti imewashwa.':'Sauti imezimwa.');saveGameState()}
  function renderSettings(){if(!$('sound-setting'))return;$('sound-setting').checked=gameState.settings.soundEnabled;$('motion-setting').checked=gameState.settings.reducedMotion;$('data-setting').checked=gameState.settings.lowDataMode;[['sound-setting','soundEnabled'],['motion-setting','reducedMotion'],['data-setting','lowDataMode']].forEach(([id,key])=>$(id).onchange=e=>{gameState.settings[key]=e.target.checked;saveGameState();document.body.classList.toggle('reduced-motion',key==='reducedMotion'&&e.target.checked)})}
  function renderAchievements(){$('achievement-list').innerHTML=achievementDefs.map(a=>`<article class="achievement-card ${gameState.achievements.includes(a.id)?'':'locked'}"><div class="badge-icon">${a.icon}</div><div><h3>${a.name} ${gameState.achievements.includes(a.id)?'✓':''}</h3><p>${a.desc}</p></div></article>`).join('')}
  function renderLeaderboard(){$('leaderboard-list').innerHTML=leaderboard.map(row=>`<div class="leader-row ${row.current?'current':''}"><span class="rank">${row.rank}</span><div><b>${row.name}${row.current?' · Wewe':''}</b><small>${row.region} · Level ${row.level} · ${row.accuracy}</small></div><span class="leader-score">${row.score}</span></div>`).join('')}
  function lessonMatches(lesson,term){const hay=[lesson.titleSw,lesson.titleEn,lesson.summary.definitionSw,lesson.abbreviation,lesson.category].join(' ').toLowerCase();return !term||hay.includes(term.toLowerCase())}
  function recommendedLessons(){const weak=Object.keys(gameState.currentQuestion?.category?{[gameState.currentQuestion.category]:1}:{});const completed=learningState.completedLessons;const candidates=validatedLessons.filter(lesson=>!completed.includes(lesson.id));return candidates.filter(lesson=>weak.some(category=>lesson.titleSw.toLowerCase().includes(category.toLowerCase()))).slice(0,3).concat(candidates.slice(0,3)).filter((lesson,index,arr)=>arr.findIndex(item=>item.id===lesson.id)===index).slice(0,3)}
  function lessonCategory(id){return KZ_LESSON_CATEGORIES.find(category=>category.id===id)}
  function renderLearningStats(){const completed=learningState.completedLessons.length;const started=Object.keys(learningState.progressByLesson).length;const stats=[['📖',started,'Masomo Yaliyoanza','blue'],['✓',completed,'Masomo Yaliyokamilika','green'],['🔥',learningState.streakDays||0,'Siku Mfululizo','orange'],['✦',learningState.learningXP||0,'Learning XP','gold']];$('learning-stats').innerHTML=stats.map(([icon,value,label,tone])=>`<article class="learning-stat ${tone}"><span class="stat-icon">${icon}</span><div><b>${value}</b><span>${label}</span></div></article>`).join('')}
  function renderContinueLesson(){const id=learningState.currentLessonId||Object.keys(learningState.progressByLesson)[0];const lesson=validatedLessons.find(item=>item.id===id);const el=$('continue-learning-card');if(!lesson){el.classList.add('empty');el.innerHTML='<div class="continue-icon">🌱</div><div class="continue-copy"><h3>Anza safari yako ya kujifunza</h3><p>Chagua somo la kwanza kutoka kwenye Maktaba ya Kodi.</p></div><button class="continue-action" data-action="discover-lessons">Vinjari masomo <span aria-hidden="true">→</span></button>';return}el.classList.remove('empty');const progress=learningProgress(lesson.id),percent=Math.max(0,Math.min(100,progress.percent||0)),remaining=Math.max(1,Math.ceil(lesson.estimatedMinutesComprehensive*(100-percent)/100));const category=lessonCategory(lesson.category);el.innerHTML=`<div class="continue-icon" style="--continue-color:${category?.color||'#087AC0'}">${lesson.icon}</div><div class="continue-copy"><span class="continue-category">${category?.titleSw||lesson.category}</span><h3>${lesson.titleSw}</h3><div class="continue-progress-meta"><span>${percent}% imekamilika</span><span>Takriban dk ${remaining} zimebaki</span></div><div class="continue-progress"><span style="width:${percent}%"></span></div></div><button class="continue-action" data-action="open-lesson" data-lesson-id="${lesson.id}">Endelea <span aria-hidden="true">→</span></button>`}
  function renderLessonCategories(active=activeLibraryCategory){const counts={};validatedLessons.forEach(lesson=>counts[lesson.category]=(counts[lesson.category]||0)+1);$('lesson-categories').innerHTML='<button class="category-chip" data-category="all" role="tab" aria-selected="'+(active==='all')+'"><span>✨</span><b>Yote</b><small>'+validatedLessons.length+' masomo</small></button>'+KZ_LESSON_CATEGORIES.map(category=>`<button class="category-chip" data-category="${category.id}" role="tab" aria-selected="${category.id===active}" style="--category:${category.color}"><span>${category.icon}</span><b>${category.titleSw}</b><small>${counts[category.id]||0} masomo</small></button>`).join('');$$('#lesson-categories [data-category]').forEach(button=>button.classList.toggle('active',button.dataset.category===active));const select=$('library-category-select');if(select)select.value=active}
  function renderRecommendations(){const el=$('recommended-lessons');const lessons=recommendedLessons();el.innerHTML=lessons.length?`<div class="library-section-title"><div><span class="section-kicker">MAPENDEKEZO MAALUM</span><h2>Kwa nini somo hili?</h2><p>Masomo yaliyochaguliwa kukusaidia kujenga msingi imara.</p></div></div><div class="recommendation-grid">${lessons.map(lesson=>{const category=lessonCategory(lesson.category);return `<article class="recommendation-card" style="--recommend-color:${category?.color||'#087AC0'}"><div class="recommendation-visual"><span>${lesson.icon}</span></div><span class="term">${category?.titleSw||lesson.category}</span><h3>${lesson.titleSw}</h3><p>Jenga msingi huu kabla ya changamoto inayofuata.</p><button class="text-button" data-action="open-lesson" data-lesson-id="${lesson.id}">Jifunze Sasa <span aria-hidden="true">→</span></button></article>`}).join('')}</div>`:''}
  function renderLibrary(filter=activeLibraryFilter,category=activeLibraryCategory,search=activeLibrarySearch){activeLibraryFilter=filter;activeLibraryCategory=category;activeLibrarySearch=search;let filtered=validatedLessons.filter(lesson=>(category==='all'||lesson.category===category)&&(filter==='all'||filter===lesson.level||filter==='completed'&&learningState.completedLessons.includes(lesson.id)||filter==='bookmarked'&&learningState.bookmarks.lessons.includes(lesson.id))&&lessonMatches(lesson,search));if(activeLibrarySort==='title')filtered.sort((a,b)=>a.titleSw.localeCompare(b.titleSw,'sw'));if(activeLibrarySort==='shortest')filtered.sort((a,b)=>a.estimatedMinutesSummary-b.estimatedMinutesSummary);if(activeLibrarySort==='xp')filtered.sort((a,b)=>b.rewards.summaryXP-a.rewards.summaryXP);const visible=filtered.slice(0,activeLibraryVisible);$('lesson-count').textContent=`Inaonyesha ${visible.length} kati ya ${filtered.length}`;$('library-empty').classList.toggle('hidden',filtered.length>0);$('library-list').innerHTML=visible.map(lesson=>{const progress=learningProgress(lesson.id),bookmarked=learningState.bookmarks.lessons.includes(lesson.id),categoryData=lessonCategory(lesson.category),levelLabel=lesson.level==='beginner'?'MWANZO':lesson.level==='intermediate'?'KATI':'JUU';return `<article class="lesson-card" style="--lesson-color:${categoryData?.color||'#087AC0'}"><div class="lesson-card-cover"><div class="lesson-icon">${lesson.icon}</div><span class="lesson-category-badge">${categoryData?.titleSw||lesson.category}</span><button class="bookmark ${bookmarked?'saved':''}" data-action="bookmark-card" data-lesson-id="${lesson.id}" aria-label="${bookmarked?'Ondoa kwenye yaliyohifadhiwa':'Hifadhi'} ${lesson.titleSw}" aria-pressed="${bookmarked}">${bookmarked?'♥':'♡'}</button></div><div class="lesson-card-body"><h3>${lesson.titleSw}</h3><p>${lesson.summary.definitionSw}</p><div class="lesson-card-meta"><span class="level-badge ${lesson.level}">${levelLabel}</span><span>◷ ${lesson.estimatedMinutesSummary} dk</span><span>✦ ${lesson.rewards.summaryXP} XP</span></div>${lesson.source?.verificationStatus==='verified'?'<div class="verified">✓ TRA Verified</div>':''}<div class="lesson-progress" aria-label="Maendeleo '+(progress.percent||0)+'%"><span style="width:${progress.percent||0}%"></span></div><div class="lesson-actions"><button data-action="open-lesson" data-lesson-id="${lesson.id}" data-mode="summary">Muhtasari</button><button data-action="open-lesson" data-lesson-id="${lesson.id}" data-mode="full">Soma Kamili <span aria-hidden="true">→</span></button></div></div></article>`}).join('');const loadMore=$('library-load-more');if(loadMore)loadMore.classList.toggle('hidden',visible.length>=filtered.length);$$('[data-lesson-filter]').forEach(button=>{const selected=button.dataset.lessonFilter===filter;button.classList.toggle('active',selected);button.setAttribute('aria-selected',selected)});renderLessonCategories(category)}
  function openLesson(id,mode='summary'){const lesson=validatedLessons.find(item=>item.id===id);if(!lesson)return;activeLesson=lesson;learningState.currentLessonId=id;learningState.currentMode=mode==='full'?'comprehensive':'summary';learningState.recentlyOpenedLessons=[id,...learningState.recentlyOpenedLessons.filter(item=>item!==id)].slice(0,8);if(!learningState.progressByLesson[id])learningState.progressByLesson[id]={percent:0,section:0,summary:false,comprehensive:false,quizScore:0};saveLearningState();renderLessonDetail();showScreen('lesson-detail-screen')}
