  function lessonAdjacent(lesson,offset){const index=validatedLessons.findIndex(item=>item.id===lesson.id);return validatedLessons[index+offset]||null}
  function renderLessonHero(lesson,full,category,bookmarked){const minutes=full?lesson.estimatedMinutesComprehensive:lesson.estimatedMinutesSummary,completed=learningState.completedLessons.includes(lesson.id);return `<header class="lesson-hero-detail" style="--lesson-accent:${category?.color||'#087ac0'}"><div class="lesson-breadcrumb"><span>Maktaba</span><b>/</b><span>${category?.titleSw||lesson.category}</span><b>/</b><strong>${lesson.titleSw}</strong></div><div class="lesson-hero-grid"><div class="lesson-hero-copy"><div class="lesson-hero-badges"><span>${category?.titleSw||lesson.category}</span><span>${full?'SOMO KAMILI':'MUHTASARI'}</span><span>◷ ${minutes} DK</span><span class="lesson-status-badge ${completed?'completed':''}">${completed?'✓ LIMEKAMILIKA':'○ HALI: LINAENDELEA'}</span></div><h1>${lesson.titleSw}</h1><p>${full?lesson.comprehensive.introductionSw:lesson.summary.definitionSw}</p><div class="lesson-hero-actions"><button class="lesson-audio-button" data-action="read-lesson">🔊 Sikiliza Somo</button><span class="lesson-xp-chip">✦ +${full?lesson.rewards.comprehensiveXP:lesson.rewards.summaryXP} XP</span></div></div><div class="lesson-hero-visual"><span class="lesson-detail-icon">${lesson.icon}</span><span class="lesson-visual-orbit orbit-one"></span><span class="lesson-visual-orbit orbit-two"></span></div></div><button id="lesson-bookmark-button" class="lesson-save-button ${bookmarked?'saved':''}" data-action="bookmark-lesson" aria-label="${bookmarked?'Ondoa somo kwenye yaliyohifadhiwa':'Hifadhi somo'}" aria-pressed="${bookmarked}">${bookmarked?'♥':'♡'} <span>${bookmarked?'Limehifadhiwa':'Hifadhi'}</span></button></header>`}
  function renderLessonModeSwitch(full){return `<div class="lesson-mode-switch" role="tablist" aria-label="Aina ya somo"><button id="lesson-summary-tab" class="${full?'':'active'}" data-action="lesson-mode-summary" role="tab" aria-selected="${!full}" aria-controls="lesson-learning-panel" tabindex="${full?'-1':'0'}"><span>📄</span> Muhtasari</button><button id="lesson-full-tab" class="${full?'active':''}" data-action="lesson-mode-full" role="tab" aria-selected="${full}" aria-controls="lesson-learning-panel" tabindex="${full?'0':'-1'}"><span>📖</span> Somo Kamili</button></div>`}
  function renderLessonSidebar(lesson,progress,category){const completed=learningState.completedLessons.includes(lesson.id),previous=lessonAdjacent(lesson,-1),next=lessonAdjacent(lesson,1),level=lesson.level==='beginner'?'Mwanzo':lesson.level==='intermediate'?'Kati':'Juu',verified=lesson.source?.verificationStatus==='verified';return `<aside class="lesson-sidebar"><section class="lesson-side-card progress-card"><div class="side-card-heading"><span>🎯</span><div><small>MAENDELEO</small><h3>Safari ya Somo</h3></div></div><div class="sidebar-progress-value"><b>${progress.percent||0}%</b><span>${completed?'Limekamilika':'Inaendelea'}</span></div><div class="sidebar-progress"><span style="width:${progress.percent||0}%"></span></div><div class="sidebar-xp"><span>✦ Learning XP</span><b id="lesson-xp-value">${learningState.learningXP}</b></div><button class="lesson-complete-button ${completed?'completed':''}" data-action="mark-lesson-complete" ${completed?'disabled':''}>${completed?'✓ Somo limekamilika':'Weka kuwa Limekamilika'}</button></section><section class="lesson-side-card"><div class="side-card-heading"><span>ℹ️</span><div><small>TAARIFA</small><h3>Kuhusu Somo</h3></div></div><dl class="lesson-facts"><div><dt>Mada</dt><dd>${category?.titleSw||lesson.category}</dd></div><div><dt>Kiwango</dt><dd>${level}</dd></div><div><dt>Muda</dt><dd>${lesson.estimatedMinutesSummary}–${lesson.estimatedMinutesComprehensive} dk</dd></div>${lesson.source?`<div><dt>Chanzo</dt><dd class="${verified?'verified-fact':''}">${verified?'✓ Imethibitishwa':'Kinapatikana'}</dd></div>`:''}</dl></section><section class="lesson-side-card lesson-side-navigation"><div class="side-card-heading"><span>🧭</span><div><small>URAMBAZAJI</small><h3>Endelea Kujifunza</h3></div></div>${previous?`<button data-action="open-lesson" data-lesson-id="${previous.id}"><span>‹</span><small>Somo lililotangulia</small><b>${previous.titleSw}</b></button>`:''}${next?`<button data-action="open-lesson" data-lesson-id="${next.id}"><span>›</span><small>Somo linalofuata</small><b>${next.titleSw}</b></button>`:''}<button data-action="library"><span>⌂</span><b>Rudi Maktaba</b></button></section></aside>`}
  function renderLessonBottomNav(lesson,full){const previous=lessonAdjacent(lesson,-1),next=lessonAdjacent(lesson,1);return `<nav class="lesson-page-navigation" aria-label="Urambazaji wa somo"><div class="lesson-navigation-heading"><div><small>ENDELEA NA SAFARI</small><strong>${next?next.titleSw:'Rudi kwenye maktaba'}</strong></div>${full?'':`<button class="lesson-primary-next" data-action="lesson-mode-full">Soma Somo Kamili <span>→</span></button>`}</div><div class="lesson-secondary-navigation">${previous?`<button data-action="open-lesson" data-lesson-id="${previous.id}">‹ Somo Lililotangulia</button>`:''}${next?`<button data-action="open-lesson" data-lesson-id="${next.id}">Somo Linalofuata ›</button>`:''}<button data-action="scroll-lesson-quiz">🧠 Quiz</button>${lesson.source?.url?'<button data-action="scroll-lesson-source">🔗 Chanzo</button>':''}</div></nav>`}
  function renderSummaryContent(lesson){return `<article class="lesson-reading-card"><span class="lesson-section-kicker">MSINGI WA SOMO</span><h2>Maana kwa Ufupi</h2><p class="lesson-lead">${lesson.summary.definitionSw}</p><ul class="lesson-points">${lesson.summary.keyPointsSw.map(item=>`<li><span>✓</span><p>${item}</p></li>`).join('')}</ul><div class="lesson-callout example"><span>💡</span><div><b>Mfano</b><p>${lesson.summary.exampleSw}</p></div></div><div class="lesson-callout reminder"><span>🔔</span><div><b>Kumbuka</b><p>${lesson.summary.reminderSw}</p></div></div></article><section class="lesson-animation-card"><div class="lesson-content-heading"><span>🔄</span><div><small>ONA UHUSIANO</small><h2>Jinsi dhana inavyofanya kazi</h2></div></div><div class="lesson-animation" data-animation="${lesson.illustrationType}">${lessonAnimation(lesson.illustrationType)}</div></section><div class="lesson-quiz-card" id="lesson-quiz"><div class="lesson-content-heading"><span>🧠</span><div><small>JIPIME</small><h2>Swali la Haraka</h2><p>Jaribu uelewa wako kabla ya kuendelea.</p></div></div>${renderQuizQuestion(lesson,0)}</div>${renderSourcePanel(lesson)}`}
  function renderFullContent(lesson){return `<article class="lesson-reading-card lesson-objectives"><span class="lesson-section-kicker">MALENGO</span><h2>Utakachojifunza</h2><ul class="objective-list">${lesson.comprehensive.objectivesSw.map(item=>`<li><span>✓</span>${item}</li>`).join('')}</ul></article>${lesson.comprehensive.sections.map((section,index)=>`<section class="lesson-section reveal-on-scroll" data-section-index="${index}"><span class="lesson-section-number">${String(index+1).padStart(2,'0')}</span><span class="lesson-section-kicker">SEHEMU ${index+1}</span><h2>${section.headingSw}</h2>${section.paragraphsSw.map(paragraph=>`<p>${paragraph}</p>`).join('')}<div class="lesson-animation" data-animation="${section.animation}">${lessonAnimation(section.animation||lesson.illustrationType)}</div></section>`).join('')}<article class="lesson-practices-card"><div><h2>⚠ Usikose</h2><ul class="mistake-list">${lesson.comprehensive.commonMistakesSw.map(item=>`<li>${item}</li>`).join('')}</ul></div><div><h2>✓ Fanya vizuri</h2><ul class="practice-list">${lesson.comprehensive.goodPracticesSw.map(item=>`<li>${item}</li>`).join('')}</ul></div></article>${renderLessonQuiz(lesson)}${renderSourcePanel(lesson)}${lesson.relatedLessons.length?`<article class="lesson-reading-card"><h2>Masomo yanayohusiana</h2><div class="lesson-related">${lesson.relatedLessons.map(id=>{const related=validatedLessons.find(item=>item.id===id);return related?`<button data-action="open-lesson" data-lesson-id="${id}">${related.titleSw} →</button>`:''}).join('')}</div></article>`:''}`}
  function renderLessonDetail(){const lesson=activeLesson;if(!lesson)return;const progress=learningProgress(lesson.id),full=learningState.currentMode==='comprehensive',category=lessonCategory(lesson.category),bookmarked=learningState.bookmarks.lessons.includes(lesson.id);$('lesson-detail-title').textContent=lesson.titleSw;$('lesson-detail-content').innerHTML=`${renderLessonHero(lesson,full,category,bookmarked)}${renderLessonModeSwitch(full)}<div id="lesson-learning-panel" class="lesson-layout" role="tabpanel" aria-labelledby="${full?'lesson-full-tab':'lesson-summary-tab'}"><div class="lesson-main-column">${full?renderFullContent(lesson):renderSummaryContent(lesson)}${renderLessonBottomNav(lesson,full)}</div>${renderLessonSidebar(lesson,progress,category)}</div>`;initializeLessonScroll()}
  function renderSourcePanel(lesson){const source=lesson.source;if(!source?.url)return '';const verified=source.verificationStatus==='verified';return `<section class="lesson-source-card ${verified?'verified-source':''}" id="lesson-source"><div class="source-trust-icon">${verified?'✓':'↗'}</div><div class="source-content"><span class="source-badge">${verified?'CHANZO RASMI KILICHOTHIBITISHWA':'CHANZO CHA SOMO'}</span><h3>${source.title}</h3><div class="source-meta">${source.lastReviewed?`<span>Imepitiwa: ${source.lastReviewed}</span>`:''}${source.financialYear?`<span>Mwaka wa fedha ${source.financialYear}</span>`:''}</div><p>Maudhui ya KodiSmart ni muhtasari wa kielimu. Fungua chanzo kilichotajwa kwa maelezo kamili na ya sasa.</p><div class="source-actions"><a href="${source.url}" target="_blank" rel="noopener noreferrer" data-source-id="${source.sourceId}">Jifunze Zaidi <span>↗</span></a><button data-action="copy-source" data-source-url="${source.url}">🔗 Nakili Link</button></div></div></section>`}
  function renderQuizQuestion(lesson,index){const q=lesson.quiz[index];return `<div class="quiz-question"><span>SWALI ${index+1}${lesson.quiz.length>1?` / ${lesson.quiz.length}`:''}</span><h3>${q.questionSw}</h3></div><div class="quiz-options" role="radiogroup" aria-label="Chagua jibu">${q.optionsSw.map((option,i)=>`<button class="quiz-option" data-action="answer-lesson-quiz" data-quiz-index="${index}" data-option-index="${i}" role="radio" aria-checked="false"><span class="quiz-radio">${String.fromCharCode(65+i)}</span><b>${option}</b><span class="quiz-result-icon"></span></button>`).join('')}</div><div class="quiz-feedback" id="quiz-feedback-${index}" aria-live="polite"></div>`}
  function renderLessonQuiz(lesson){return `<section class="lesson-quiz-card" id="lesson-quiz"><div class="lesson-content-heading"><span>🧠</span><div><small>JIPIME</small><h2>Knowledge Check</h2><p>Jibu maswali yote ili kukamilisha somo.</p></div></div><div id="lesson-quiz-area">${renderQuizQuestion(lesson,0)}</div></section>`}
  function initializeLessonScroll(){if(lessonObserver)lessonObserver.disconnect();lessonObserver=new IntersectionObserver(entries=>entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');const index=Number(entry.target.dataset.sectionIndex);if(activeLesson&&index>=learningProgress(activeLesson.id).section){const progress=learningProgress(activeLesson.id);progress.section=index;progress.percent=Math.max(progress.percent,Math.round(((index+1)/activeLesson.comprehensive.sections.length)*75));learningState.progressByLesson[activeLesson.id]=progress;saveLearningState()}}}),{threshold:.16});$$('.reveal-on-scroll').forEach(element=>lessonObserver.observe(element));}
  function confettiBurst(){if(prefersReducedMotion())return;const colors=['#F4B942','#18A66A','#25A7F0','#F68B3C'];for(let i=0;i<18;i++){const s=document.createElement('span');s.style.cssText=`position:fixed;z-index:100;left:${45+Math.random()*10}%;top:42%;width:7px;height:12px;background:${colors[i%4]};transform:rotate(${Math.random()*180}deg);border-radius:3px;pointer-events:none`;document.body.appendChild(s);s.animate([{transform:'translate(0,0) rotate(0)',opacity:1},{transform:`translate(${(Math.random()-.5)*300}px,${180+Math.random()*250}px) rotate(${Math.random()*720}deg)`,opacity:0}],{duration:850+Math.random()*700,easing:'cubic-bezier(.2,.8,.3,1)'}).onfinish=()=>s.remove()}}
  function startDemo(){
    demoSnapshot=clone(gameState); demoMode=true;
    gameState.player={...gameState.player,name:'Amina',region:'Dar es Salaam',avatar:'avatar-4'};
    gameState.unlockedLevels=[1,2,3]; gameState.currentLevel=1; gameState.currentQuestionIndex=0; gameState.score=0; gameState.combo=0; gameState.bestCombo=0; gameState.lives=3;
    sessionQuestions=['l1-tra','l1-tin','l1-tax','l1-efd'].map(id=>KZ_QUESTIONS.find(q=>q.id===id));
    showScreen('game-screen'); loadQuestion(sessionQuestions[0]); toast('Demo inaanza — Amina anajifunza TRA.'); setTimeout(()=>demoSelectAnswer(0),1100);
  }
  function demoSelectAnswer(index){
    if(!demoMode||activeScreen!=='game-screen')return;
    const q=gameState.currentQuestion;
    if(index===2){gameState.timerRemaining=3;updateTimerUI();toast('Muda unaenda! Joka Kodi anakaribia.');return}
    const answer=q.type==='multiple-choice'?q.answer:normalize(q.answer);
    [...answer].forEach((letter,i)=>setTimeout(()=>{const ball=balls.find(b=>!b.selected&&b.text===letter);if(ball)handleLetterSelection(ball,ball.el)},180*i));
    if(index===1)setTimeout(()=>{const wrong=balls.find(b=>!b.selected);if(wrong)handleLetterSelection(wrong,wrong.el)},120);
    setTimeout(()=>{if(index<3){gameState.currentQuestionIndex=index+1;showScreen('game-screen');loadQuestion(sessionQuestions[index+1]);setTimeout(()=>demoSelectAnswer(index+1),1400)}else{completeLevel();setTimeout(()=>{renderTaxBenefitsHome();showScreen('tax-benefits-screen');setTimeout(()=>{renderLibrary();showScreen('learning-library-screen');setTimeout(()=>{renderLeaderboard();showScreen('leaderboard-screen');setTimeout(()=>showScreen('about-screen'),2200)},2200)},2200)},2500)}},1900+answer.length*180);
  }
  function exitDemo(){if(!demoMode)return;demoMode=false;if(demoSnapshot)gameState=demoSnapshot;saveGameState();showScreen('welcome-screen');renderApp();toast('Umetoka kwenye demo.')}
  function benefitProject(id){return KZ_COMMUNITY_PROJECTS.find(project=>project.id===id)}
  function projectStage(progress){return progress>=100?4:progress>=75?3:progress>=50?2:progress>=25?1:0}
  function projectVisual(project){const progress=taxBenefitsState.projectProgress[project.id]||0;const stage=projectStage(progress);const visuals={school:['🪧','🧱','🏗️','🏫','🏫👩‍🏫'],healthCentre:['🪧','🧱','🏥','🏥🩺','🏥🚑'],road:['🟫','🚜','🛣️','🛣️🟡','🛣️🚗'],water:['🏜️','🪣','🚰','💧','💧🧑‍🤝‍🧑'],market:['⬜','🧱','🏪','🏪📦','🏪🧑‍🤝‍🧑'],streetlights:['🌆','🪵','💡','💡💡','🌃💡'],digitalCentre:['🏚️','🧱','🏢','🏢💻','🏢📱'],environment:['🌱','🌱🌱','🌳','🌳🧹','🌳🧑‍🤝‍🧑']}[project.id]||['▫️','▫️','▫️','▫️','▫️'];return {stage,visual:visuals[stage],label:`${stage*25}%`}}
  function renderDevelopmentPoints(){const counter=$('development-points-counter');if(counter)counter.textContent=`✦ ${taxBenefitsState.developmentPoints}`}
  function renderTaxBenefitsWidget(){const el=$('tax-benefits-dashboard-widget');if(!el)return;const completed=taxBenefitsState.completedLessons.length;el.innerHTML=`<span class="widget-points">✦ ${taxBenefitsState.developmentPoints}</span><h3>🏫 Kodi Inajenga Taifa</h3><p>Jifunze jinsi mapato ya pamoja yanavyohusiana na huduma za umma.</p><button data-action="tax-benefits">Chunguza Faida za Kodi →</button><small style="display:block;margin-top:8px;color:#cdebf4">${completed}/12 maeneo yamechunguzwa</small>`}
  function renderTaxBenefitsHome(){renderDevelopmentPoints();const content=$('tax-benefits-content');if(!content)return;content.innerHTML=`<section class="tax-benefits-hero"><span class="mini-pill">MATOKEO BAADA YA KULIPA KODI</span><h2>Kodi Inajenga Taifa</h2><p> Kodi zinazokusanywa pamoja huchangia mapato ya serikali yanayotumika kugharamia huduma za umma na maendeleo ya taifa.</p><div class="development-flow"><div class="development-node"><b>👥</b>Wananchi na Biashara</div><span class="development-arrow">↓</span><div class="development-node"><b>✦</b>Mapato ya Pamoja</div><span class="development-arrow">↓</span><div class="development-node"><b>🏛️</b>Huduma za Umma</div><span class="development-arrow">↓</span><div class="development-node"><b>🌱</b>Maendeleo</div></div><div class="tax-benefit-actions"><button class="primary-button" data-action="explore-benefits">Chunguza Faida</button><button class="secondary-button" data-action="start-development-journey">Anza Safari ya Maendeleo</button></div></section><div class="benefit-disclaimer">${KZ_TAX_BENEFIT_DISCLAIMER}</div><div class="benefit-section-title"><div><span class="mini-pill">MAENEO YA HUDUMA</span><h2>Chagua eneo la kujifunza</h2></div></div><div class="benefit-categories">${KZ_TAX_BENEFIT_CATEGORIES.map(category=>{const progress=taxBenefitsState.completedSummaries.includes(category.id)?100:0;return `<article class="benefit-card"><div class="benefit-card-illustration">${category.icon}</div><h3>${category.titleSw}</h3><p>${category.summarySw}</p><div class="benefit-card-meta"><span>+${category.points} Pointi</span><span>${progress}%</span></div><div class="benefit-progress"><span style="width:${progress}%"></span></div><button data-action="open-benefit" data-category-id="${category.id}">Jifunze Zaidi →</button></article>`}).join('')}</div><div class="benefit-section-title"><div><span class="mini-pill">MFANO WA JAMII</span><h2>Jenga kwa Pointi</h2></div><span class="lesson-count">Pointi za mchezo</span></div><div class="benefit-disclaimer">Pointi hizi ni sehemu ya mchezo na hazihusiani na malipo halisi ya kodi.</div><div class="community-projects">${KZ_COMMUNITY_PROJECTS.map(renderProjectCard).join('')}</div><div class="benefit-section-title"><div><span class="mini-pill">KABLA NA BAADA</span><h2>Ona tofauti kwa mfano</h2></div></div><div class="comparison-wrap">${renderComparison()}<p class="comparison-caption">Huu ni mfano wa kielimu unaoonyesha mabadiliko ya jamii; si rekodi ya matumizi ya serikali wala ahadi ya mradi maalum.</p></div><div class="benefit-section-title"><div><span class="mini-pill">MATOKEO BAADA YA KULIPA KODI</span><h2>Mchakato wa pamoja</h2></div></div><div class="benefit-timeline">${renderTaxBenefitTimeline()}</div><div class="benefit-section-title"><div><span class="mini-pill">MTAZAMO TOFAUTI</span><h2>Faida kwa kila mmoja</h2></div></div><div class="business-benefits-panel"><h3>Faida kwa Mfanyabiashara</h3><p>Utunzaji wa records na uelewa wa wajibu unaweza kuimarisha utaratibu wa biashara, mipango na mawasiliano na taasisi rasmi.</p></div><div class="citizen-benefits-panel"><h3>Faida kwa Mwananchi</h3><p>Elimu ya kodi huongeza uelewa wa mapato ya pamoja, risiti, huduma rasmi na ushiriki wa kiraia.</p></div><div class="government-benefits-panel"><h3>Faida kwa Serikali na TRA</h3><p>Elimu inaweza kusaidia voluntary compliance, kupunguza mkanganyiko na kuimarisha uelewa wa njia rasmi.</p></div><div class="benefit-badges">${KZ_TAX_BENEFIT_BADGES.map(badge=>`<div class="benefit-badge ${taxBenefitsState.unlockedBadges.includes(badge.id)?'':'locked'}"><b>${badge.icon}</b><span>${badge.title}</span></div>`).join('')}</div><div class="benefit-source"><h3>Jifunze Zaidi</h3><p>Maelezo haya ni muhtasari wa kielimu. Kwa maelezo rasmi na ya sasa, fungua vyanzo rasmi vya TRA.</p>${Object.values(KZ_TAX_BENEFIT_SOURCES).map(source=>`<a href="${source.url}" target="_blank" rel="noopener noreferrer">${source.title} ↗</a>`).join('')}</div>`}
  function renderProjectCard(project){const visual=projectVisual(project);const progress=taxBenefitsState.projectProgress[project.id]||0;const canContribute=taxBenefitsState.developmentPoints>=project.requiredPointsPerStage&&progress<100;return `<article class="project-card"><div class="project-scene"><span class="project-visual">${visual.visual}</span><span class="project-stage-label">Hatua ${visual.stage} · ${visual.label}</span></div><h3>${project.icon} ${project.titleSw}</h3><p>Maendeleo ya mfano, si rekodi ya mradi halisi.</p><div class="project-progress"><span style="width:${progress}%"></span></div><div class="project-actions"><small>${progress}% · ${project.requiredPointsPerStage} pt</small><button data-action="contribute-project" data-project-id="${project.id}" ${canContribute?'':'disabled'}>Changia Pointi</button></div></article>`}
  function renderComparison(){return `<div class="comparison-scene"><div class="comparison-after">🛣️💡🏫🌳💧<span class="after-label">Baada · mfano</span></div><div id="comparison-before" class="comparison-before">🟫🏚️🌱<span class="before-label">Kabla · mfano</span></div></div><input id="comparison-slider" class="comparison-slider" type="range" min="0" max="100" value="50" aria-label="Kabla na baada" data-action="comparison-slider">`}
  function renderTaxBenefitTimeline(){return [['Mlipakodi anatambua wajibu wake','Uelewa huanza kwa taarifa sahihi.'],['Biashara inaweka kumbukumbu','Records na risiti husaidia uwazi wa shughuli.'],['Malipo yanafanyika kupitia njia rasmi','Tumia chanzo rasmi kuthibitisha njia.'],['Mapato yanaingia kwenye mfumo wa serikali','Mchakato unahusisha taasisi na hatua mbalimbali.'],['Bajeti na mipango rasmi huandaliwa','Mipango ya umma huandaliwa kwa mifumo husika.'],['Huduma na miradi ya umma hutekelezwa','Utekelezaji unaweza kutofautiana kwa eneo na wakati.'],['Wananchi na biashara hushiriki maendeleo','Mazingira bora hujengwa kwa uwajibikaji wa pamoja.']].map((step,i)=>`<div class="timeline-step"><b>${i+1}</b><div><h4>${step[0]}</h4><p>${step[1]}</p></div></div>`).join('')}
  function openBenefitCategory(id){const category=KZ_TAX_BENEFIT_CATEGORIES.find(item=>item.id===id);if(!category)return;activeBenefitCategory=category;taxBenefitsState.lastOpenedCategory=id;taxBenefitsState.exploredCategories=[...new Set([...taxBenefitsState.exploredCategories,id])];saveTaxBenefitsState();renderBenefitDetail();}
  function renderBenefitDetail(){const category=activeBenefitCategory;const source=KZ_TAX_BENEFIT_SOURCES[category.sourceId];const project=benefitProject(category.projectId);const full=taxBenefitsState.currentMode==='comprehensive';const q=taxBenefitScenarios.find(item=>item.category===category.id)||taxBenefitScenarios[0];$('tax-benefits-content').innerHTML=`<button class="back-button" data-action="tax-benefits-home">‹ Faida za Kodi</button><div class="benefit-detail"><div class="benefit-detail-header"><span class="benefit-big-icon">${category.icon}</span><span class="mini-pill">${full?'SOMO KAMILI':'MUHTASARI'}</span><h2>${category.titleSw}</h2><p>${category.summarySw}</p></div><div class="benefit-mode-switch"><button class="${full?'':'active'}" data-action="benefit-mode-summary">Muhtasari</button><button class="${full?'active':''}" data-action="benefit-mode-full">Somo Kamili</button></div>${full?`<div class="benefit-comprehensive"><h3>Utangulizi</h3><p>${category.summarySw} Katika somo hili tunaangalia uhusiano wa mapato ya pamoja, huduma na uwajibikaji bila kudai kuwa malipo ya mtu mmoja yanafadhili mradi maalum.</p><div class="benefit-key-flow"><span>👥<br>Wananchi</span><b>→</b><span>✦<br>Mapato ya pamoja</span><b>→</b><span>🏛️<br>Bajeti</span><b>→</b><span>🌱<br>Huduma</span></div><h3>Mfano wa maisha</h3><p>${category.exampleSw}</p><h3>Jukumu la uwajibikaji</h3><p>Uelewa wa kodi, records, risiti na vyanzo rasmi huimarisha ushiriki wa wananchi na biashara. Changamoto zinaweza kuwepo, hivyo taarifa za sasa zitafutwe kwenye chanzo rasmi.</p><div class="lesson-animation benefit-animation">${benefitAnimation(category.animationId)}</div><div class="benefit-scenario"><h3>Scenario</h3><p>${q.questionSw}</p><div class="scenario-options">${q.optionsSw.map((option,i)=>`<button data-action="benefit-scenario-answer" data-option-index="${i}" data-correct="${q.correctOption}">${option}</button>`).join('')}</div><div id="benefit-scenario-feedback" class="scenario-feedback"></div></div>${renderBenefitQuiz(category)}<div class="benefit-summary"><h3>Muhtasari</h3><ul class="benefit-points">${category.keyPointsSw.map(point=>`<li>${point}</li>`).join('')}</ul></div></div>`:`<div class="benefit-summary"><h3>Maana kwa Ufupi</h3><p>${category.summarySw}</p><ul class="benefit-points">${category.keyPointsSw.map(point=>`<li>${point}</li>`).join('')}</ul><div class="benefit-practical-example"><b>Mfano</b><br>${category.exampleSw}</div><div class="benefit-disclaimer"><b>Kumbuka:</b> ${category.reminderSw}</div><div class="lesson-animation benefit-animation">${benefitAnimation(category.animationId)}</div><button class="primary-button full-width-action" data-action="complete-benefit-summary" data-category-id="${category.id}">${taxBenefitsState.completedSummaries.includes(category.id)?'Muhtasari umekamilika ✓':'Kamilisha Muhtasari +10 XP'}</button><button class="secondary-button full-width-action" data-action="benefit-mode-full">Soma Somo Kamili →</button></div>`}<div class="benefit-source"><h3>Jifunze Zaidi</h3><p>${source.title}. Imethibitishwa kwa matumizi ya elimu; ${source.financialYear?`mwaka wa fedha ${source.financialYear}`:'thibitisha taarifa za sasa'}.</p><p>Maelezo haya ni muhtasari wa kielimu. Kwa maelezo rasmi na ya sasa, fungua vyanzo rasmi vya TRA.</p><a href="${source.url}" target="_blank" rel="noopener noreferrer">Fungua Chanzo Rasmi ↗</a></div></div>`;renderDevelopmentPoints();}
  function benefitAnimation(id){const map={school:'🏫🧑‍🏫',health:'🏥🩺🚑',road:'🚜🛣️🚗',water:'🚰💧🧑‍🤝‍🧑',market:'🏪📦🧑‍🤝‍🧑',streetlights:'🌃💡💡',digital:'🏢💻📱',environment:'🌱🌳🧹'};return `<div class="flow-row"><div class="flow-node">${map[id]||'🌱'}</div><div class="flow-arrow">→</div><div class="flow-node">${id==='school'?'Mazingira ya kujifunzia':id==='health'?'Huduma za afya':id==='road'?'Usafiri':id==='water'?'Maji safi':id==='market'?'Biashara':id==='streetlights'?'Mwanga':id==='digital'?'Huduma mtandaoni':'Jamii'}</div></div>`}
  function renderBenefitQuiz(category){const questions=taxBenefitScenarios.filter(item=>item.category===category.id||item.category==='community').slice(0,3);return `<div class="benefit-quiz"><h3>Knowledge Check</h3>${questions.map((item,index)=>`<div class="benefit-quiz-question"><p>${index+1}. ${item.questionSw}</p><div class="benefit-quiz-options">${item.optionsSw.map((option,optionIndex)=>`<button data-action="benefit-quiz-answer" data-question-index="${index}" data-option-index="${optionIndex}" data-correct="${item.correctOption}">${option}</button>`).join('')}</div><div id="benefit-quiz-feedback-${index}" class="scenario-feedback"></div></div>`).join('')}</div>`}
  function awardDevelopmentPoints(amount){taxBenefitsState.developmentPoints+=amount;saveTaxBenefitsState();renderDevelopmentPoints();renderTaxBenefitsWidget();toast(`+${amount} Pointi za Maendeleo`);unlockBenefitBadges();}
