  function unlockBenefitBadges(){const unlocked=taxBenefitsState.unlockedBadges;if(taxBenefitsState.completedLessons.length>=1&&!unlocked.includes('development-student'))unlocked.push('development-student');if(taxBenefitsState.completedSummaries.includes('education')&&!unlocked.includes('education-friend'))unlocked.push('education-friend');if(taxBenefitsState.completedSummaries.includes('health')&&!unlocked.includes('health-ally'))unlocked.push('health-ally');if(Object.values(taxBenefitsState.projectProgress).some(value=>value>=50)&&!unlocked.includes('infrastructure-builder'))unlocked.push('infrastructure-builder');if(taxBenefitsState.projectProgress.water>=100&&!unlocked.includes('water-friend'))unlocked.push('water-friend');if(taxBenefitsState.completedSummaries.includes('environment')&&!unlocked.includes('environment-guardian'))unlocked.push('environment-guardian');if(taxBenefitsState.completedSummaries.includes('digital')&&!unlocked.includes('digital-expert'))unlocked.push('digital-expert');if(taxBenefitsState.completedSummaries.length>=12&&!unlocked.includes('nation-builder'))unlocked.push('nation-builder');if(taxBenefitsState.developmentPoints>=200&&!unlocked.includes('tax-benefits-master'))unlocked.push('tax-benefits-master');saveTaxBenefitsState()}
